-- Esquema orientativo PostgreSQL; adaptar al motor elegido.
CREATE TABLE usuarios (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, email VARCHAR(255) UNIQUE NOT NULL, password_hash TEXT NOT NULL, rol VARCHAR(30) NOT NULL);
CREATE TABLE pasajeros (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, usuario_id BIGINT REFERENCES usuarios(id), cedula VARCHAR(20) UNIQUE, nombre VARCHAR(180) NOT NULL, email VARCHAR(255));
CREATE TABLE cooperativas (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nombre VARCHAR(180) NOT NULL);
CREATE TABLE buses (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, cooperativa_id BIGINT NOT NULL REFERENCES cooperativas(id), placa VARCHAR(20) UNIQUE NOT NULL);
CREATE TABLE asientos (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, bus_id BIGINT NOT NULL REFERENCES buses(id), numero INTEGER NOT NULL, tipo VARCHAR(15) NOT NULL, UNIQUE(bus_id,numero));
CREATE TABLE viajes (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, bus_id BIGINT NOT NULL REFERENCES buses(id), origen VARCHAR(120) NOT NULL, destino VARCHAR(120) NOT NULL, salida TIMESTAMP NOT NULL);
CREATE TABLE reservas (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, comprador_id BIGINT NOT NULL REFERENCES usuarios(id), estado VARCHAR(30) NOT NULL DEFAULT 'pendiente', creada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE boletos (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, reserva_id BIGINT NOT NULL REFERENCES reservas(id), pasajero_id BIGINT NOT NULL REFERENCES pasajeros(id), viaje_id BIGINT NOT NULL REFERENCES viajes(id), asiento_id BIGINT NOT NULL REFERENCES asientos(id), estado VARCHAR(30) NOT NULL DEFAULT 'reservado', UNIQUE(viaje_id,asiento_id));
CREATE TABLE pagos (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, reserva_id BIGINT NOT NULL REFERENCES reservas(id), metodo VARCHAR(30) NOT NULL, monto NUMERIC(10,2) NOT NULL, estado VARCHAR(30) NOT NULL DEFAULT 'pendiente');
